// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // fund the contract with a fuzzed amount so a real selfdestruct has an effect to show
        vm.deal(address(c), amount);

        // owner (deployer, the test contract) invokes the entry point
        vm.prank(address(this));
        c.sudicideAnyone();

        // General rule: after the owner calls sudicideAnyone, the contract is destroyed
        // (no code remains at its address) for ANY fuzzed balance.
        assertTrue(address(c).code.length == 0, "contract must self-destruct on owner call");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Forwarder fwd;

    function setUp() public { c = new C(); fwd = new Forwarder(address(c)); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(fwd) && actor.code.length == 0);
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);
        uint256 before = actor.balance;
        bool ok;
        vm.startPrank(actor, actor); // actor is both msg.sender to fwd and tx.origin for the whole chain
        try fwd.suicide() { ok = true; } catch { ok = false; }
        vm.stopPrank();
        // Reference rule: the self-destruct refund goes to the direct caller (the forwarder),
        // never to tx.origin; the originating EOA's balance must be untouched.
        assertTrue(ok && actor.balance == before);
    }
}

contract Forwarder {
    C c;
    constructor(address target) { c = C(target); }
    function suicide() external { c.sudicideAnyone(); }
}

