pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public { c = new C(); caller = new Caller(); }

    function testFuzz_property(uint256 amount, address origin) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        // The caller must be a CONTRACT distinct from the EOA tx.origin so that
        // msg.sender != tx.origin; a fuzzed address alone is an EOA, so we route
        // the call through a deployed contract caller while fuzzing the origin EOA.
        vm.assume(origin != address(0) && origin != address(caller) && origin != address(c) && origin != address(this));
        vm.deal(address(c), amount);
        // set both msg.sender (contract caller) and tx.origin (fuzzed EOA)
        vm.startPrank(address(caller), origin);
        c.sudicideAnyone();
        vm.stopPrank();
        // Rule: the refund of c's entire balance is delivered to the direct caller
        // (msg.sender), never to the EOA origin. Reference: holds for all inputs.
        // Mutant (payable(tx.origin)): origin receives the funds, caller gets nothing.
        assertTrue(address(caller).balance == amount && address(c).balance == 0);
    }
}

contract Caller {
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = address(this); }

    function testFuzz_property(uint256 amount, address origin) public {
        vm.assume(origin != address(0));
        vm.assume(origin != owner);
        vm.assume(origin != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);

        vm.deal(owner, amount);
        vm.startPrank(owner, owner);
        (bool okDep, ) = payable(address(c)).call{value: amount}("");
        vm.stopPrank();
        assertTrue(okDep);

        uint256 originBalBefore = origin.balance;

        // direct caller is the owner (required by __onlyOwner), but the
        // transaction origin is a different, arbitrary address.
        vm.startPrank(owner, origin);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        vm.stopPrank();
        assertTrue(ok);

        // RULE: c's self-destruct refund is received by the direct caller,
        // so an unrelated tx.origin never gains funds from it.
        assertTrue(origin.balance == originBalBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // fund the contract; owner of c is this test contract (deployer)
        vm.deal(address(this), amount);
        (bool okSend, ) = address(c).call{value: amount}("");
        assertTrue(okSend);

        uint256 callerBefore = address(this).balance;

        // owner drives c through sudicideAnyone
        c.sudicideAnyone();

        // Rule: the caller (owner) receives the contract's whole balance.
        assertTrue(address(this).balance == callerBefore + amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller) public {
        require(caller != address(c));

        bytes memory data = abi.encodeWithSelector(c.sudicideAnyone.selector);
        bool ok;
        (ok, ) = address(c).call(data);

        // Rule: a non-owner caller cannot trigger sudicideAnyone (call must revert).
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint dummy) public payable {
        require(true);
        bool reverted; try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // The test contract is not the owner recorded at C's construction,
        // so on P (onlyOwner modifier) the call must revert; on M it succeeds.
        assert(reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c, address deployer) {
        // The rule only holds when this test contract is NOT the owner that
        // C recorded at construction (C's owner is whoever deployed it).
        // Exclude the degenerate case where this contract itself deployed C.
        require(deployer != address(this));
        c = _c;
    }
    function run(uint dummy) public payable {
        require(dummy == dummy); // no extra input precondition needed
        bool reverted; try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // The test contract is not the owner recorded at C's construction,
        // so on P (onlyOwner modifier) the call must revert; on M it succeeds.
        assert(reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c, address deployer) {
        // The rule only holds when this test contract is NOT the owner that
        // C recorded at construction (C's owner is whoever deployed it).
        // Exclude the degenerate case where this contract itself deployed C.
        require(deployer != address(this));
        c = _c;
    }
    function run(uint dummy) public payable {
        require(dummy == dummy); // no extra input precondition needed
        // Setup: move C out of the state where this contract is the recorded
        // owner. By exercising the privileged selfdestruct once, C's code is
        // destroyed, so any subsequent sudicideAnyone call reverts for the
        // (now former) owner that this contract was in the counterexample.
        c.sudicideAnyone();
        bool reverted; try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // The test contract is not the owner recorded at C's construction,
        // so on P (onlyOwner modifier) the call must revert; on M it succeeds.
        assert(reverted);
    }
    receive() external payable { }
}
